// Общий код для управления ссылкой кандидата (#45f435, F-23): id кандидата из list_candidates, окно «ניהול הקישור»
// на /candidates/<id>/report, окно подтверждения, текущая ссылка (data-testid candidate-link), экран S-11 у гостя.
import { Page, Locator, Response } from '@playwright/test';
import { expect } from '../../fixtures';
import { candidateRow } from '../candidate-call/support';

export const S11 = {
  title: 'הקישור לא פעיל',
  replaced: /ייתכן שנשלח אליכם קישור חדש\. אם לא קיבלתם אותו, פנו לצוות הגיוס של/,
  notFound: 'לא מצאנו את הקישור. בדקו שהעתקתם אותו במלואו, או פנו לצוות הגיוס ששלח לכם אותו.',
  expired: 'תוקף הקישור פג, או שכבר השתמשו בו',
  technical: /זו שאלה טכנית בלבד, והיא לא משפיעה על המועמדות שלכם/,
  contact: 'לפנות לצוות הגיוס',
};

/** Поиск объекта с full_name === name в ответе list_candidates (форма ответа может быть массивом или {items}). */
function findId(o: unknown, name: string): string {
  if (Array.isArray(o)) {
    for (const x of o) {
      const r = findId(x, name);
      if (r) return r;
    }
  } else if (o && typeof o === 'object') {
    const rec = o as Record<string, unknown>;
    if (rec.full_name === name && typeof rec.id === 'string') return rec.id;
    for (const v of Object.values(rec)) {
      const r = findId(v, name);
      if (r) return r;
    }
  }
  return '';
}

/** business: id кандидата по имени (из ответа rpc/list_candidates при открытии списка и поиске). */
export async function candidateId(page: Page, name: string): Promise<string> {
  let id = '';
  const onResp = async (r: Response) => {
    if (!r.url().includes('/rpc/list_candidates')) return;
    try {
      id = id || findId(await r.json(), name);
    } catch {
      /* не JSON */
    }
  };
  page.on('response', onResp);
  await candidateRow(page, name);
  await expect.poll(() => id, { message: `нет id кандидата «${name}» в ответах list_candidates` }).not.toBe('');
  page.off('response', onResp);
  return id;
}

/** business: /candidates/<id>/report → «ניהול הקישור». Возвращает окно (панель с заголовком «ניהול הקישור»). */
export async function openManage(page: Page, id: string): Promise<Locator> {
  await page.goto(`/candidates/${id}/report`);
  await page.getByTestId('manage-candidate-link').first().click();
  const panel = page
    .locator('[role=dialog], aside, section')
    .filter({ has: page.getByRole('heading', { name: 'ניהול הקישור' }) })
    .last();
  await expect(panel).toBeVisible();
  return panel;
}

/** Окно подтверждения действия (есть кнопка «חזרה») → нажать кнопку действия; ждёт POST rpc с подходящим именем. */
export async function confirmAction(page: Page, button: string, rpc: RegExp): Promise<Response> {
  const dialog = page
    .locator('[role=dialog], [role=alertdialog]')
    .filter({ has: page.getByRole('button', { name: 'חזרה', exact: true }) })
    .last();
  await expect(dialog).toBeVisible();
  const res = page.waitForResponse((r) => rpc.test(r.url()) && r.request().method() === 'POST');
  await dialog.getByRole('button', { name: button, exact: true }).click();
  const r = await res;
  expect(r.status(), `${r.url().split('/rpc/')[1]} должен вернуть 200`).toBe(200);
  await expect(dialog).toBeHidden();
  return r;
}

/** Текущая ссылка кандидата в окне «ניהול הקישור» (href data-testid candidate-link). */
export async function linkIn(panel: Locator): Promise<string> {
  const a = panel.getByTestId('candidate-link');
  await expect(a).toBeVisible();
  const href = (await a.getAttribute('href')) || '';
  expect(href, 'ссылка кандидата /c/<token>').toMatch(/\/c\/[A-Za-z0-9_-]{20,}$/);
  return href;
}

/** business: текущая ссылка кандидата (открыть окно, прочитать, закрыть). */
export async function currentLink(page: Page, id: string): Promise<string> {
  const panel = await openManage(page, id);
  const href = await linkIn(panel);
  await page.keyboard.press('Escape');
  return href;
}

/** Гость: ссылка не работает — S-11 «הקישור לא פעיל», техническое объяснение, путь к команде; старта нет. */
export async function expectInactive(guest: Page, link: string, reason: string | RegExp = S11.replaced) {
  await guest.goto(link);
  await expect(guest.getByRole('heading', { name: S11.title })).toBeVisible({ timeout: 30_000 });
  await expect(guest.getByText(reason)).toBeVisible();
  await expect(guest.getByText(S11.technical)).toBeVisible();
  await expect(guest.getByRole('button', { name: S11.contact }).or(guest.getByRole('link', { name: S11.contact }))).toBeVisible();
  await expect(guest.getByRole('button', { name: 'בוא נתחיל' })).toHaveCount(0);
}

/** Гость: ссылка работает — приветствие с «בוא נתחיל» (попытка не начинается). */
export async function expectWelcome(guest: Page, link: string) {
  await guest.goto(link);
  await expect(guest.getByRole('button', { name: 'בוא נתחיל' })).toBeVisible({ timeout: 30_000 });
  await expect(guest.getByRole('heading', { name: S11.title })).toHaveCount(0);
}
